import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import * as dat from 'lil-gui'

/**
 * Base
 */
// Debug
const gui = new dat.GUI()

// Canvas
const canvas = document.querySelector('canvas.webgl')

// Scene
const scene = new THREE.Scene()


/**
 * Load Baked
 */
const loadTexture = new THREE.TextureLoader()
const textureBaked = loadTexture.load("/textures/simpleShadow.jpg")



/**
 * Lights
 */
// Ambient light
const ambientLight = new THREE.AmbientLight(0xffffff, 0.3)
gui.add(ambientLight, 'intensity').min(0).max(1).step(0.001)
scene.add(ambientLight)

// Directional light
const directionalLight = new THREE.DirectionalLight(0xffffff, 0.3)
directionalLight.position.set(2, 2, - 1)
gui.add(directionalLight, 'intensity').min(0).max(1).step(0.001)
gui.add(directionalLight.position, 'x').min(- 5).max(5).step(0.001)
gui.add(directionalLight.position, 'y').min(- 5).max(5).step(0.001)
gui.add(directionalLight.position, 'z').min(- 5).max(5).step(0.001)
scene.add(directionalLight)
directionalLight.castShadow = false
directionalLight.shadow.mapSize.width = 1024
directionalLight.shadow.mapSize.height = 1024
//? Edit Le near et far permet d'éviter certain glish
directionalLight.shadow.camera.near = 1
directionalLight.shadow.camera.far = 8
directionalLight.shadow.camera.top = directionalLight.shadow.camera.top / 2
directionalLight.shadow.camera.right = directionalLight.shadow.camera.right / 2
directionalLight.shadow.camera.bottom = directionalLight.shadow.camera.bottom / 2
directionalLight.shadow.camera.left = directionalLight.shadow.camera.left / 2
directionalLight.shadow.radius = 6

const directionalLightCameraHelper = new THREE.CameraHelper(directionalLight.shadow.camera)
directionalLightCameraHelper.visible = false
gui.add(directionalLightCameraHelper, 'visible').name("shadow cam direct ligh")
scene.add(directionalLightCameraHelper)

//? Important
/*
Only the following types of lights support shadows:
    PointLight
    DirectionalLight
    SpotLight
*/

const directLoghtHelper = new THREE.DirectionalLightHelper(directionalLight)
directLoghtHelper.visible = false
gui.add(directLoghtHelper, 'visible').name("light helper")
scene.add(directLoghtHelper)


const spotLight = new THREE.SpotLight(0xffffff, 0.4, 10, Math.PI * 0.3)
spotLight.castShadow = false
spotLight.shadow.mapSize.width = 1024
spotLight.shadow.mapSize.height = 1024
spotLight.shadow.camera.fov = 30
spotLight.shadow.camera.far = 8
spotLight.shadow.camera.near = 1

spotLight.position.set(0, 2, 2)
scene.add(spotLight)
scene.add(spotLight.target)

const spotLightCameraHelper = new THREE.CameraHelper(spotLight.shadow.camera)
spotLightCameraHelper.visible = false
gui.add(spotLightCameraHelper, 'visible').name("shadow cam spotligt")
scene.add(spotLightCameraHelper)

const pointlight = new THREE.PointLight(0Xffffff, 0.6)
pointlight.castShadow = false
pointlight.position.set(-2, 4, 1)
pointlight.shadow.mapSize.width = 1024
pointlight.shadow.mapSize.height = 1024
pointlight.shadow.camera.far = 8
pointlight.shadow.camera.near = 1
scene.add(pointlight)

const helperlightPoint = new THREE.CameraHelper(pointlight.shadow.camera)
helperlightPoint.visible = false
gui.add(helperlightPoint, 'visible').name("shadow cam pointligh")
scene.add(helperlightPoint)

/**
 * Materials
 */
const material = new THREE.MeshStandardMaterial()
material.roughness = 0.7
material.side = 2
gui.add(material, 'metalness').min(0).max(1).step(0.001)
gui.add(material, 'roughness').min(0).max(1).step(0.001)

/**
 * Objects
 */
const sphere = new THREE.Mesh(
    new THREE.SphereGeometry(0.5, 32, 32),
    material
)
sphere.castShadow = false

const plane = new THREE.Mesh(
    new THREE.PlaneGeometry(5, 5),
    material
    // new THREE.MeshBasicMaterial({
    //     map: textureBacked
    // })
)
plane.rotation.x = - Math.PI * 0.5
plane.position.y = - 0.5
plane.receiveShadow = true

scene.add(sphere, plane)

const sphereShadow = new THREE.Mesh(
    new THREE.PlaneGeometry(1.5, 1.5),
    new THREE.MeshBasicMaterial({
        color: 0x000000,
        transparent: true,
        alphaMap: textureBaked
    })
)
sphereShadow.rotation.x = - Math.PI * 0.5
sphereShadow.position.y = plane.position.y + 0.01

scene.add(sphere, sphereShadow, plane)

/**
 * Sizes
 */
const sizes = {
    width: window.innerWidth,
    height: window.innerHeight
}

window.addEventListener('resize', () => {
    // Update sizes
    sizes.width = window.innerWidth
    sizes.height = window.innerHeight

    // Update camera
    camera.aspect = sizes.width / sizes.height
    camera.updateProjectionMatrix()

    // Update renderer
    renderer.setSize(sizes.width, sizes.height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
})

/**
 * Camera
 */
// Base camera
const camera = new THREE.PerspectiveCamera(75, sizes.width / sizes.height, 0.01, 200)
camera.position.x = 1
camera.position.y = 1
camera.position.z = 2
scene.add(camera)

// Controls
const controls = new OrbitControls(camera, canvas)
controls.enableDamping = true

/**
 * Renderer
 */
const renderer = new THREE.WebGLRenderer({
    canvas: canvas
})
renderer.setSize(sizes.width, sizes.height)
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
renderer.shadowMap.enabled = true
renderer.shadowMap.type = THREE.PCFSoftShadowMap
/*
Different types of algorithms can be applied to shadow maps:
    THREE.BasicShadowMap: Very performant but lousy quality
    THREE.PCFShadowMap: Less performant but smoother edges
    THREE.PCFSoftShadowMap: Less performant but even softer edges
    THREE.VSMShadowMap: Less performant, more constraints, can have unexpected results
*/

/**
 * Animate
 */
const clock = new THREE.Clock()

const tick = () => {
    const elapsedTime = clock.getElapsedTime()
    sphere.position.set(
        Math.cos(clock.getElapsedTime()) * 1.5,
        Math.abs(Math.sin(clock.getElapsedTime())),
        Math.sin(clock.getElapsedTime()) * 1.5
    )
    sphereShadow.position.x = sphere.position.x
    sphereShadow.position.z = sphere.position.z
    sphereShadow.material.opacity = (1 - sphere.position.y) * 0.5

    // Update controls
    controls.update()

    // Render
    renderer.render(scene, camera)

    // Call tick again on the next frame
    window.requestAnimationFrame(tick)
}

tick()

