import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import * as dat from 'lil-gui'

/**
 * Base
 */
// Debug
const gui = new dat.GUI()

// Canvas
const canvas = document.querySelector('canvas.webgl')

// Scene
const scene = new THREE.Scene()

const fog = new THREE.Fog('#262837', 5, 20)
scene.fog = fog

/**
 * Textures
 */
const textureLoader = new THREE.TextureLoader()
const doorColorTexture = textureLoader.load('/textures/door/color.jpg')
const doorAlphaTexture = textureLoader.load('/textures/door/alpha.jpg')
const doorAmbientOcclusionTexture = textureLoader.load('/textures/door/ambientOcclusion.jpg')
const doorHeightTexture = textureLoader.load('/textures/door/height.jpg')
const doorNormalTexture = textureLoader.load('/textures/door/normal.jpg')
const doorMetalnessTexture = textureLoader.load('/textures/door/metalness.jpg')
const doorRoughnessTexture = textureLoader.load('/textures/door/roughness.jpg')

const bricksColorTexture = textureLoader.load('/textures/bricks/color.jpg')
const bricksAmbientOcclusionTexture = textureLoader.load('/textures/bricks/ambientOcclusion.jpg')
const bricksNormalTexture = textureLoader.load('/textures/bricks/normal.jpg')
const bricksRoughnessTexture = textureLoader.load('/textures/bricks/roughness.jpg')

const grassColorTexture = textureLoader.load('/textures/grass/color.jpg')
const grassAmbientOcclusionTexture = textureLoader.load('/textures/grass/ambientOcclusion.jpg')
const grassNormalTexture = textureLoader.load('/textures/grass/normal.jpg')
const grassRoughnessTexture = textureLoader.load('/textures/grass/roughness.jpg')

grassColorTexture.repeat.set(8, 8)
grassAmbientOcclusionTexture.repeat.set(8, 8)
grassNormalTexture.repeat.set(8, 8)
grassRoughnessTexture.repeat.set(8, 8)

grassColorTexture.wrapS = THREE.RepeatWrapping
grassAmbientOcclusionTexture.wrapS = THREE.RepeatWrapping
grassNormalTexture.wrapS = THREE.RepeatWrapping
grassRoughnessTexture.wrapS = THREE.RepeatWrapping

grassColorTexture.wrapT = THREE.RepeatWrapping
grassAmbientOcclusionTexture.wrapT = THREE.RepeatWrapping
grassNormalTexture.wrapT = THREE.RepeatWrapping
grassRoughnessTexture.wrapT = THREE.RepeatWrapping

/**
 * House
 */
// Group House
const groupHouse = new THREE.Group()
scene.add(groupHouse)
// House Wall
const house = new THREE.Mesh(
    new THREE.BoxGeometry(4, 2.3, 4),
    new THREE.MeshStandardMaterial({
        map: bricksColorTexture,
        aoMap: bricksAmbientOcclusionTexture,
        normalMap: bricksNormalTexture,
        roughnessMap: bricksRoughnessTexture
    })
)
house.geometry.setAttribute('uv2', new THREE.Float32BufferAttribute(house.geometry.attributes.uv.array, 2))
house.position.y = 2.3 / 2 + 0.001
groupHouse.add(house)

// Roof top
const roof = new THREE.Mesh(
    new THREE.ConeGeometry(3.4, 2.2, 4, 1, false),
    new THREE.MeshStandardMaterial({ color: 'red', wireframe: false })
)
roof.position.y = house.position.y + 2
roof.rotation.y = 0.25 * Math.PI
groupHouse.add(roof)

// Door top
const door = new THREE.Mesh(
    new THREE.PlaneGeometry(1.5, 1.6, 42, 42),
    new THREE.MeshStandardMaterial({
            map: doorColorTexture,
            alphaMap: doorAlphaTexture,
            transparent: true,
            aoMap: doorAmbientOcclusionTexture,
            displacementMap: doorHeightTexture,
            displacementScale: 0.1,
            normalMap: doorNormalTexture,
            metalnessMap: doorMetalnessTexture,
            roughnessMap: doorRoughnessTexture,
            // wireframe: true
        })
)
door.geometry.setAttribute('uv2', new THREE.Float32BufferAttribute(door.geometry.attributes.uv.array, 2))
door.position.y = house.position.y / 2 + 0.01
door.position.z = 2 + 0.01
groupHouse.add(door)

// Bush1
const bushGeometry = new THREE.SphereGeometry(1, 16, 16)
const bushMaterial = new THREE.MeshStandardMaterial({ color: '#89c854' })
const bush1 = new THREE.Mesh(bushGeometry, bushMaterial)
bush1.scale.set(0.5, 0.5, 0.5)
bush1.position.set(0.8, 0.2, 2.2)
// Bush2
const bush2 = new THREE.Mesh(bushGeometry, bushMaterial)
bush2.scale.set(0.25, 0.25, 0.25)
bush2.position.set(1.4, 0.1, 2.1)
// Bush3
const bush3 = new THREE.Mesh(bushGeometry, bushMaterial)
bush3.scale.set(0.4, 0.4, 0.4)
bush3.position.set(- 0.8, 0.1, 2.2)
// Bush4
const bush4 = new THREE.Mesh(bushGeometry, bushMaterial)
bush4.scale.set(0.15, 0.15, 0.15)
bush4.position.set(- 1, 0.05, 2.6)
groupHouse.add(bush1, bush2, bush3, bush4)

// Group Graves
const groupGraves = new THREE.Group()
scene.add(groupGraves)

const graveGeometry = new THREE.BoxGeometry(0.6, 0.8, 0.2)
const graveMaterial = new THREE.MeshStandardMaterial({ color: '#b2b6b1' })

for (let i = 0; i < 32; i++) {
    let posRangeX = 6 + Math.random() * 6
    let posRangeZ = 6 + Math.random() * 6
    const graveMesh = new THREE.Mesh(
        graveGeometry,
        graveMaterial
    )
    graveMesh.position.y = 0.3
    graveMesh.position.x = Math.cos(Math.random() * Math.PI * 2) * posRangeX
    graveMesh.position.z = Math.sin(Math.random() * Math.PI * 2) * posRangeZ
    graveMesh.lookAt(new THREE.Vector3())
    graveMesh.rotation.x = Math.sin(Math.random()) * 0.1
    graveMesh.castShadow = true
    groupGraves.add(graveMesh)
}


// Floor
const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(25, 25),
    new THREE.MeshStandardMaterial({
        map: grassColorTexture,
        aoMap: grassAmbientOcclusionTexture,
        normalMap: grassNormalTexture,
        roughnessMap: grassRoughnessTexture,
        // side: 2
    })
)
floor.geometry.setAttribute('uv2', new THREE.Float32BufferAttribute(floor.geometry.attributes.uv.array, 2))
floor.rotation.x = - Math.PI * 0.5
floor.position.y = 0
scene.add(floor)

/**
 * Lights
 */
// Ambient light
const ambientLight = new THREE.AmbientLight('#b9d5ff', 0.12)
gui.add(ambientLight, 'intensity').min(0).max(1).step(0.001)
scene.add(ambientLight)

// Directional light
const moonLight = new THREE.DirectionalLight('#b9d5ff', 0.12)
moonLight.position.set(4, 5, - 2)
gui.add(moonLight, 'intensity').min(0).max(1).step(0.001).name("light direct intensity")
gui.add(moonLight.position, 'x').min(- 5).max(5).step(0.001).name("light direct  x")
gui.add(moonLight.position, 'y').min(- 5).max(5).step(0.001).name("light direct  y")
gui.add(moonLight.position, 'z').min(- 5).max(5).step(0.001).name("light direct  z")
scene.add(moonLight)

const doorLight = new THREE.PointLight('#ff7d46', 1, 8)
doorLight.position.set(0, 2.2, 4)
house.add(doorLight)


const ghost1 = new THREE.PointLight('#ff00ff', 2, 6)
scene.add(ghost1)

const ghost2 = new THREE.PointLight('#00ffff', 2, 6)
scene.add(ghost2)

const ghost3 = new THREE.PointLight('#ffff00', 2, 6)
scene.add(ghost3)

/**
 * Sizes
 */
const sizes = {
    width: window.innerWidth,
    height: window.innerHeight
}

window.addEventListener('resize', () => {
    // Update sizes
    sizes.width = window.innerWidth
    sizes.height = window.innerHeight

    // Update camera
    camera.aspect = sizes.width / sizes.height
    camera.updateProjectionMatrix()

    // Update renderer
    renderer.setSize(sizes.width, sizes.height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
})

/**
 * Camera
 */
// Base camera
const camera = new THREE.PerspectiveCamera(75, sizes.width / sizes.height, 0.1, 100)
camera.position.x = 4
camera.position.y = 2
camera.position.z = 5
scene.add(camera)

// Controls
const controls = new OrbitControls(camera, canvas)
controls.enableDamping = true

/**
 * Renderer
 */
const renderer = new THREE.WebGLRenderer({
    canvas: canvas
})
renderer.setSize(sizes.width, sizes.height)
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
renderer.setClearColor('#262837')
renderer.shadowMap.enabled = true
moonLight.castShadow = true
doorLight.castShadow = true
ghost1.castShadow = true
ghost2.castShadow = true
ghost3.castShadow = true
house.castShadow = true
bush1.castShadow = true
bush2.castShadow = true
bush3.castShadow = true
bush4.castShadow = true
floor.receiveShadow = true
moonLight.shadow.mapSize.width = 256
moonLight.shadow.mapSize.height = 256
moonLight.shadow.camera.far = 15
doorLight.shadow.mapSize.width = 256
doorLight.shadow.mapSize.height = 256
doorLight.shadow.camera.far = 7
ghost1.shadow.mapSize.width = 256
ghost1.shadow.mapSize.height = 256
ghost1.shadow.camera.far = 7
ghost2.shadow.mapSize.width = 256
ghost2.shadow.mapSize.height = 256
ghost2.shadow.camera.far = 7
ghost3.shadow.mapSize.width = 256
ghost3.shadow.mapSize.height = 256
ghost3.shadow.camera.far = 7
renderer.shadowMap.type = THREE.PCFSoftShadowMap

/**
 * Animate
 */
const clock = new THREE.Clock()

const tick = () => {
    const elapsedTime = clock.getElapsedTime()


    ghost1.position.x = Math.sin(Math.PI * clock.getElapsedTime() * 0.02) * 6
    ghost1.position.z = Math.cos(Math.PI * clock.getElapsedTime() * 0.02) * 6
    ghost3.position.y = Math.sin(Math.PI * clock.getElapsedTime()) * 6

    ghost2.position.x = -(Math.sin(Math.PI * 2 * clock.getElapsedTime() * 0.05) * 11)
    ghost2.position.z = -(Math.cos(Math.PI * 2 * clock.getElapsedTime() * 0.05) * 11)
    ghost3.position.y = Math.cos(Math.PI * clock.getElapsedTime() * 0.4) * -2

    ghost3.position.x = Math.sin(Math.PI * 1/2 * clock.getElapsedTime() * 0.2) * 3
