    ghost3.position.y = Math.cos(Math.PI * clock.getElapsedTime() * 0.2) * 2

    // Update controls
    controls.update()

    // Render
    renderer.render(scene, camera)

    // Call tick again on the next frame
    window.requestAnimationFrame(tick)
}

tick()

